ns16:scriptTask.ns16:script:
tw.local.searchResultPanelVIS = "Editable";
tw.local.displayErrorMessage = "";
if(tw.local.searchResult.length == 0)
{	
	tw.local.displayErrorMessage = "No Result Found";
	tw.local.searchResultPanelVIS = "None";

}
