//for (var i =0 ; i< tw.local.searchResult.length ;i++)
//{
//  tw.local.searchResult[i].requestDate = formatDate(tw.local.searchResult[i].requestDate);
//}

tw.local.valid = true;

if(tw.local.searchResult.listAllSelectedIndices == "" || tw.local.searchResult.listAllSelectedIndices == null)
{
	alert("Kindly select a specific record to show its details");
	tw.local.valid = false;

}
else if(tw.local.valid == true){

	var index = tw.local.searchResult.listAllSelectedIndices;
	
	tw.local.requestType = tw.local.searchResult[index].requestType;
	
	//if( tw.local.requestType == tw.epv.RequestType.Amendment || tw.epv.RequestType.Create)
	if( tw.local.requestType == "amend" || tw.local.requestType == "create"|| tw.local.requestType == "recreate")
	{
		tw.local.screenType = "create";
	}
	
	else if(tw.local.requestType  == tw.epv.RequestType.Reversal || tw.local.requestType == tw.epv.RequestType.Closure)
	
	{
		tw.local.screenType = "reversal";
	}
	
	else if(tw.local.requestType == tw.epv.RequestType.Collection)
	
	{
		tw.local.screenType = "collection";
	}
}

