ns16:scriptTask.ns16:script:
if(tw.local.requestType == tw.epv.RequestType.Reversal){
	tw.local.reversalReasonVIS = "Readonly";
	tw.local.closureReasonVIS = "None";
}
else
{
	tw.local.reversalReasonVIS = "None";
	tw.local.closureReasonVIS = "Readonly";
}

if(tw.local.requestType == "create" || tw.local.requestType == "Create")
{
	tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.requestNo+"ODC"+"/Issuance";
}
else if(tw.local.requestType == "amend")
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Amendment "+tw.local.odcRequest.requestNo;
else if(tw.local.requestType == tw.epv.RequestType.Collection)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Collection "+tw.local.odcRequest.requestNo;
	
 else if(tw.local.requestType == tw.epv.RequestType.Closure)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Closure "+tw.local.odcRequest.requestNo;
	
 else if(tw.local.requestType  == tw.epv.RequestType.Reversal || tw.local.requestType == "reversal")
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Reversal "+tw.local.odcRequest.requestNo;
else if(tw.local.requestType  == "recreate")
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Recreate "+tw.local.odcRequest.requestNo;

/////Setting Visibility of fields of cv
/////--------------------------------------------------------
/*Basic Details CV Visibility*/
///////////////////////////////
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create){
	tw.local.parentRequestNoVIS = "None";
}	
else{
	tw.local.parentRequestNoVIS = "Readonly";
}	
if(tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate  || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "Readonly";
}
else{
tw.local.contractStageVIS = "NONE";
}
/*Document Generation Section*/
///////////////////////////////
if(tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment || tw.local.odcRequest.BasicDetails.requestType  == tw.epv.RequestType.Recreate){
	tw.local.requestTypeVIS = "Readonly";
	tw.local.collectingBankRefVIS = "Readonly";
}
else{
	tw.local.requestTypeVIS = "NONE";	
	tw.local.collectingBankRefVIS = "NONE";
}
//////MultiTenorDates Vis
if(tw.local.odcRequest.BasicDetails.paymentTerms.name != "001")//not equal sight
{
 	tw.local.multiTenorDatesVIS = "Readonly" ;
}
else
{	
tw.local.multiTenorDatesVIS = "None" ;
}
	
	
	if(tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate){
	tw.local.collectingBankRefVIS = "Readonly";
	}
	
	else{
	tw.local.collectingBankRefVIS = "None";
